CREATE TABLE audit_event(id UUID PRIMARY KEY,event_id VARCHAR(36) NOT NULL UNIQUE,event_type VARCHAR(80) NOT NULL,correlation_id VARCHAR(36),causation_id VARCHAR(36),trace_id VARCHAR(100),aggregate_id VARCHAR(100),source VARCHAR(100) NOT NULL,payload_json TEXT NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,recorded_at TIMESTAMPTZ NOT NULL);CREATE INDEX idx_audit_correlation ON audit_event(correlation_id);CREATE INDEX idx_audit_aggregate ON audit_event(aggregate_id);